class V33Activity : AppCompatActivity() {
    private lateinit var db: V32DatabaseHelper
    private val navy = Color.rgb(17, 48, 82)
    private val blue = Color.rgb(35, 112, 220)
    private val teal = Color.rgb(0, 145, 135)
    private val green = Color.rgb(20, 150, 80)
    private val red = Color.rgb(210, 60, 60)
    private val amber = Color.rgb(225, 145, 20)
    private val pageBg = Color.rgb(245, 249, 253)
    private val labelBg = Color.rgb(232, 243, 253)
