    private data class Draft(val borrower: Long, val guarantor: Long?, val type: String, val principal: Double, val roi: Double, val tenor: Int, val method: String, val start: String, val end: String, val installment: Double, val payable: Double)

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        db = V32DatabaseHelper(this)
        onBackPressedDispatcher.addCallback(this, object : androidx.activity.OnBackPressedCallback(true) {
            override fun handleOnBackPressed() { if (backAction != null) backAction!!.invoke() else finish() }
        })
        if (db.hasUser()) dashboard() else login()
    }

    private fun dp(v: Int) = (v * resources.displayMetrics.density).toInt()
    private fun rounded(fill: Int, stroke: Int = Color.TRANSPARENT, radius: Int = 14) = android.graphics.drawable.GradientDrawable().apply { setColor(fill); cornerRadius = dp(radius).toFloat(); if (stroke != Color.TRANSPARENT) setStroke(dp(1), stroke) }
    private fun root() = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL; setPadding(dp(14), dp(10), dp(14), dp(18)); setBackgroundColor(pageBg) }
    private fun label(s: String) = TextView(this).apply { text = s; textSize = 12f; setTextColor(navy); setPadding(dp(9), dp(3), dp(9), dp(3)); background = rounded(labelBg, Color.rgb(205, 224, 242), 8) }
    private fun edit(hint: String, max: Int? = null, numeric: Boolean = false) = EditText(this).apply { this.hint = hint; textSize = 15f; setSingleLine(true); setPadding(dp(12), 0, dp(12), 0); background = rounded(Color.WHITE, Color.rgb(210, 221, 233), 12); if (numeric) inputType = InputType.TYPE_CLASS_NUMBER or InputType.TYPE_NUMBER_FLAG_DECIMAL; max?.let { filters = arrayOf(InputFilter.LengthFilter(it)) }; imeOptions = EditorInfo.IME_ACTION_NEXT }
    private fun field(title: String, e: EditText, next: EditText? = null): LinearLayout { val box = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL; setPadding(0, dp(2), 0, dp(2)) }; box.addView(label(title), LinearLayout.LayoutParams(-1, dp(23))); box.addView(e, LinearLayout.LayoutParams(-1, dp(45))); e.setOnEditorActionListener { _, action, _ -> if (action == EditorInfo.IME_ACTION_NEXT && next != null) { next.requestFocus(); true } else false }; return box }
    private fun phone(title: String) = edit(title, 10).apply { inputType = InputType.TYPE_CLASS_PHONE; keyListener = android.text.method.DigitsKeyListener.getInstance("0123456789") }
    private fun button(s: String, color: Int = blue, action: () -> Unit) = Button(this).apply { text = s; isAllCaps = false; textSize = 13f; setTextColor(Color.WHITE); background = rounded(color, color, 22); minHeight = dp(44); setPadding(dp(12), 0, dp(12), 0); setOnClickListener { action() } }
    private fun show(v: View) { setContentView(ScrollView(this).apply { isFillViewport = true; setBackgroundColor(pageBg); addView(v) }) }
    private fun page(title: String, sub: String, back: (() -> Unit)? = null): LinearLayout { val r = root(); val h = LinearLayout(this).apply { orientation = LinearLayout.HORIZONTAL; gravity = Gravity.CENTER_VERTICAL }; val t = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL; layoutParams = LinearLayout.LayoutParams(0, -2, 1f) }; t.addView(TextView(this).apply { text = title; textSize = 23f; setTextColor(navy) }); t.addView(TextView(this).apply { text = sub; textSize = 12f; setTextColor(Color.GRAY) }); h.addView(t); h.addView(button("HOME", navy) { dashboard() }, LinearLayout.LayoutParams(dp(76), dp(42))); r.addView(h); r.addView(Space(this).apply { layoutParams = LinearLayout.LayoutParams(1, dp(5)) }); backAction = back; return r }
    private fun money(v: Double) = String.format(Locale.US, "₹%,.2f", v)
    private fun roi(v: Double) = String.format(Locale.US, "%.2f%%", v)

    private fun login() { val r = root(); r.addView(TextView(this).apply { text = "UDHAARDAAR"; textSize = 28f; gravity = Gravity.CENTER; setTextColor(Color.WHITE); background = rounded(navy, navy, 20); setPadding(0, dp(15), 0, dp(15)) }); r.addView(TextView(this).apply { text = "Smart informal-credit manager"; textSize = 14f; gravity = Gravity.CENTER; setTextColor(navy); setPadding(0, dp(4), 0, dp(8)) }); val name = edit("Enter full name"); val mobile = phone("10-digit mobile number"); val address = edit("Full address"); val email = edit("Email (optional)"); r.addView(field("FULL NAME *", name)); r.addView(field("MOBILE NUMBER *", mobile)); r.addView(field("FULL ADDRESS *", address)); r.addView(field("EMAIL", email)); val img = ImageView(this).apply { setImageResource(android.R.drawable.ic_menu_camera); scaleType = ImageView.ScaleType.CENTER_CROP; background = rounded(Color.WHITE, Color.LTGRAY, 14); layoutParams = LinearLayout.LayoutParams(-1, dp(110)) }; r.addView(img); r.addView(button("ADD PROFILE PHOTO (OPTIONAL)", teal) { pickPhoto(img) }); r.addView(button("CREATE PROFILE + VERIFY", green) { if (name.text.isNullOrBlank() || mobile.text.length != 10 || address.text.isNullOrBlank()) { toast("Enter name, 10-digit mobile and address"); return@button }; otpDialog("Lender profile verification") { db.saveUser("USR-${System.currentTimeMillis()}", name.text.toString().trim(), mobile.text.toString(), address.text.toString().trim(), email.text.toString().trim(), selectedPhoto?.toString()); dashboard() } }); show(r) }

    private fun dashboard() { val u = db.userData(); val r = page("Dashboard", "Compact credit control centre", ::dashboard); r.addView(TextView(this).apply { text = "Good day, ${u?.name ?: "Lender"}"; textSize = 20f; setTextColor(navy) }); val stats = LinearLayout(this).apply { orientation = LinearLayout.HORIZONTAL }; stat(stats, money(db.totalCredit("Credit Given")), "Credit Given", blue) { history("Credit Given") }; stat(stats, money(db.totalCredit("Credit Received")), "Credit Taken", teal) { history("Credit Received") }; r.addView(stats); val stats2 = LinearLayout(this).apply { orientation = LinearLayout.HORIZONTAL }; stat(stats2, db.dueCount(false).toString(), "Due", amber) { repayments(false) }; stat(stats2, db.dueCount(true).toString(), "Overdue", red) { repayments(true) }; r.addView(stats2); actionCard(r, "＋  REGISTER CREDIT", blue) { creditFlow() }; actionCard(r, "⌕  BORROWER PROFILES", teal) { profiles("BORROWER") }; actionCard(r, "₹  REPAYMENT CENTRE", green) { repayments(false) }; actionCard(r, "▣  CREDIT HISTORY", navy) { history(null) }; actionCard(r, "◎  LENDER PROFILE", teal) { lender() }; actionCard(r, "⌁  DOCUMENTS & CONSENT", amber) { documents() }; r.addView(button("LOG OUT", Color.DKGRAY) { login() }); show(r) }
    private fun stat(parent: LinearLayout, value: String, title: String, color: Int, action: () -> Unit) { val x = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL; gravity = Gravity.CENTER; setPadding(dp(4), dp(9), dp(4), dp(9)); background = rounded(Color.WHITE, Color.rgb(220, 228, 238), 14); setOnClickListener { action() } }; x.addView(TextView(this).apply { text = value; textSize = 17f; setTextColor(color); gravity = Gravity.CENTER }); x.addView(TextView(this).apply { text = title; textSize = 10f; setTextColor(Color.GRAY); gravity = Gravity.CENTER }); parent.addView(x, LinearLayout.LayoutParams(0, -2, 1f).apply { setMargins(dp(3), dp(3), dp(3), dp(3)) }) }
    private fun actionCard(r: LinearLayout, title: String, color: Int, action: () -> Unit) { r.addView(button(title, color, action), LinearLayout.LayoutParams(-1, dp(46)).apply { setMargins(0, dp(3), 0, dp(3)) }) }

    private fun profiles(role: String) { val r = page("${role.lowercase().replaceFirstChar { it.uppercase() }} Profiles", "Search and manage profiles", ::dashboard); val q = edit("Name / mobile / PAN / Aadhaar / Unique ID"); r.addView(field("SEARCH", q)); val list = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL }; fun refresh() { list.removeAllViews(); db.searchProfiles(role, q.text.toString()).forEach { p -> rcard(list, "${p.name}  •  ${p.mobile}", "${p.id} • ${p.city}, ${p.state}", blue) { if (role == "BORROWER") summary(p.rowId) else profile(role, p.rowId) } }; if (list.childCount == 0) list.addView(TextView(this).apply { text = "No matching profile"; setTextColor(Color.GRAY); setPadding(0, dp(8), 0, dp(8)) }) }; r.addView(button("SEARCH", blue) { refresh() }); r.addView(button("CREATE NEW PROFILE", green) { profile(role, null) }); r.addView(list); refresh(); show(r) }
    private fun rcard(parent: LinearLayout, title: String, sub: String, color: Int, action: () -> Unit) { val b = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL; setPadding(dp(12), dp(8), dp(12), dp(8)); background = rounded(Color.WHITE, Color.rgb(220, 228, 238), 12); setOnClickListener { action() } }; b.addView(TextView(this).apply { text = title; textSize = 15f; setTextColor(navy) }); b.addView(TextView(this).apply { text = sub; textSize = 11f; setTextColor(Color.GRAY) }); parent.addView(b, LinearLayout.LayoutParams(-1, -2).apply { setMargins(0, dp(3), 0, dp(3)) }) }

    private fun profile(role: String, id: Long?) { val p = id?.let { db.profileData(it) }; val r = page("${role.lowercase().replaceFirstChar { it.uppercase() }} Profile", "Edit profile, photo and location", ::dashboard); val name = edit("Full name"); val mob = phone("10-digit mobile"); val alt = edit("Alternate mobile"); val addr = edit("Full address"); val city = edit("City"); val state = edit("State"); val pin = edit("6-digit PIN", 6, true); val email = edit("Email"); val pan = edit("PAN"); val aad = edit("12-digit Aadhaar", 12, true); val occ = edit("Occupation / Business"); val biz = edit("Business name"); val gst = edit("GSTIN"); name.setText(p?.name ?: ""); mob.setText(p?.mobile ?: ""); alt.setText(p?.alternate ?: ""); addr.setText(p?.address ?: ""); city.setText(p?.city ?: ""); state.setText(p?.state ?: ""); pin.setText(p?.pin ?: ""); email.setText(p?.email ?: ""); pan.setText(p?.pan ?: ""); aad.setText(p?.aadhaar ?: ""); occ.setText(p?.occupation ?: ""); biz.setText(p?.business ?: ""); gst.setText(p?.gstin ?: ""); val all = listOf(name, mob, alt, addr, city, state, pin, email, pan, aad, occ, biz, gst); all.forEachIndexed { i, e -> r.addView(field(listOf("FULL NAME *","MOBILE NUMBER *","ALTERNATE MOBILE","ADDRESS *","CITY","STATE","PIN CODE","EMAIL","PAN","AADHAAR","OCCUPATION / BUSINESS","BUSINESS NAME","GSTIN")[i], e, all.getOrNull(i + 1))) }; pin.addTextChangedListener(object : android.text.TextWatcher { override fun beforeTextChanged(s: CharSequence?, st: Int, c: Int, a: Int) {} override fun onTextChanged(s: CharSequence?, st: Int, before: Int, count: Int) { if (s?.length == 6) lookupPin(s.toString(), city, state, addr) } override fun afterTextChanged(s: android.text.Editable?) {} }); r.addView(button("USE CURRENT LOCATION", teal) { fillLocation(addr, city, state, pin) }); r.addView(button("OPEN ADDRESS IN MAPS", navy) { val q = Uri.encode(addr.text.toString().ifBlank { "India" }); startActivity(Intent(Intent.ACTION_VIEW, Uri.parse("geo:0,0?q=$q"))) }); val img = ImageView(this).apply { layoutParams = LinearLayout.LayoutParams(-1, dp(135)); scaleType = ImageView.ScaleType.CENTER_CROP; background = rounded(Color.WHITE, Color.LTGRAY, 14); p?.photo?.let { setImageURI(Uri.parse(it)) }; if (p?.photo.isNullOrBlank()) setImageResource(android.R.drawable.ic_menu_camera) }; r.addView(img); r.addView(button("CHANGE PHOTO (OPTIONAL)", teal) { pickPhoto(img) }); r.addView(button(if (p == null) "SAVE PROFILE" else "UPDATE PROFILE", green) { if (name.text.isNullOrBlank() || mob.text.length != 10 || addr.text.isNullOrBlank()) { toast("Name, 10-digit mobile and address are required"); return@button }; val rid = db.upsertProfile(p?.rowId, role, p?.id ?: "${if (role == "BORROWER") "BOR" else "GUA"}-${System.currentTimeMillis()}", name.text.toString().trim(), mob.text.toString(), alt.text.toString(), addr.text.toString(), city.text.toString(), state.text.toString(), pin.text.toString(), email.text.toString(), pan.text.toString().uppercase(), aad.text.toString(), occ.text.toString(), biz.text.toString(), gst.text.toString().uppercase(), selectedPhoto?.toString() ?: p?.photo); if (rid > 0) { selectedPhoto = null; profiles(role) } else toast("Could not save profile") }); show(r) }

    private fun summary(id: Long) { val p = db.profileData(id) ?: return; val credits = db.credits().filter { it.borrowerId == p.id }; val paid = credits.sumOf { db.paidForCredit(it.id) }; val open = credits.count { it.status == "ACTIVE" }; val outstanding = credits.sumOf { (it.payable - db.paidForCredit(it.id)).coerceAtLeast(0.0) }; val schedules = db.schedules(false).filter { s -> credits.any { it.creditId == s.creditId } }; val overdue = schedules.count { it.status == "OVERDUE" }; val closed = credits.count { (it.payable - db.paidForCredit(it.id)) <= 0.01 }; val timely = credits.sumOf { c -> db.schedules(false).count { s -> s.creditId == c.creditId && s.status == "PAID" } }; val delayed = credits.sumOf { c -> db.schedules(true).count { s -> s.creditId == c.creditId } }; val r = page("Borrower Credit Profile", "Full credit behaviour before new credit", ::profilesBorrowers); r.addView(TextView(this).apply { text = p.name; textSize = 23f; setTextColor(navy) }); r.addView(TextView(this).apply { text = "${p.id}  •  ${p.mobile}"; textSize = 12f; setTextColor(Color.GRAY) }); val grid = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL }; metric(grid, "Credit availed", credits.size.toString(), blue); metric(grid, "Amount availed", money(credits.sumOf { it.amount }), blue); metric(grid, "Timely repayments", timely.toString(), green); metric(grid, "Delayed repayments", delayed.toString(), red); metric(grid, "Accounts closed", closed.toString(), teal); metric(grid, "Open credits", "$open / ${money(outstanding)}", amber); metric(grid, "Overdue", "$overdue / ${money(outstanding)}", red); metric(grid, "Total repayments", money(paid), green); r.addView(grid); r.addView(button("VIEW CREDIT SCORE", navy) { scoreDialog(p.id, credits) }); r.addView(button("REGISTER CREDIT FOR THIS BORROWER", blue) { creditFlow(id) }); r.addView(button("EDIT PROFILE", teal) { profile("BORROWER", id) }); show(r) }
    private fun profilesBorrowers() = profiles("BORROWER")
    private fun metric(parent: LinearLayout, title: String, value: String, color: Int) { val row = LinearLayout(this).apply { gravity = Gravity.CENTER_VERTICAL; background = rounded(Color.WHITE, Color.rgb(220, 228, 238), 10); setPadding(dp(10), dp(6), dp(10), dp(6)) }; row.addView(TextView(this).apply { text = title; textSize = 12f; setTextColor(navy); layoutParams = LinearLayout.LayoutParams(0, -2, 1f) }); row.addView(TextView(this).apply { text = value; textSize = 14f; setTextColor(color) }); parent.addView(row, LinearLayout.LayoutParams(-1, dp(38)).apply { setMargins(0, dp(2), 0, dp(2)) }) }

    private fun scoreDialog(profileId: String, credits: List<V32DatabaseHelper.CreditRow>) { val total = credits.size; val paidSchedules = credits.sumOf { c -> db.schedules(false).count { it.creditId == c.creditId && it.status == "PAID" } }; val overdue = credits.sumOf { c -> db.schedules(true).count { it.creditId == c.creditId } }; val timelyRatio = if (paidSchedules + overdue == 0) 1.0 else paidSchedules.toDouble() / (paidSchedules + overdue); val utilBase = credits.sumOf { it.amount }.coerceAtLeast(1.0); val outstanding = credits.sumOf { (it.payable - db.paidForCredit(it.id)).coerceAtLeast(0.0) }; val utilisation = (1.0 - (outstanding / utilBase)).coerceIn(0.0, 1.0); val age = if (total == 0) 0.5 else (0.5 + total.coerceAtMost(12) / 24.0).coerceAtMost(1.0); val mix = if (credits.map { it.type }.distinct().size >= 2) 1.0 else 0.7; val newCredit = if (total <= 2) 0.8 else 1.0; val score = (300 + 600 * (0.35 * timelyRatio + 0.30 * utilisation + 0.15 * age + 0.10 * mix + 0.10 * newCredit)).toInt().coerceIn(300, 900); AlertDialog.Builder(this).setTitle("Udhaardaar Credit Score: $score").setMessage("300–900 scale. Factors: payment history 35%, utilisation 30%, credit age 15%, credit mix 10%, new credit 10%.\n\nThis is an Udhaardaar/CIBIL-style behavioural score, not an official CIBIL score and does not reproduce CIBIL's proprietary algorithm.").setPositiveButton("OK", null).show() }

    private fun creditFlow(preselected: Long? = null) { val r = page("Register Credit", "Step 1 • borrower and repayment terms", ::dashboard); val q = edit("Search borrower"); r.addView(field("BORROWER SEARCH", q)); val selected = TextView(this).apply { textSize = 13f; setTextColor(navy); setPadding(dp(8), dp(6), dp(8), dp(6)); background = rounded(Color.WHITE, Color.LTGRAY, 10) }; r.addView(selected); var borrower = preselected; preselected?.let { db.profileData(it)?.let { p -> selected.text = "Selected: ${p.name} • ${p.id}" } }; r.addView(button("SEARCH BORROWER", teal) { val rows = db.searchProfiles("BORROWER", q.text.toString()).take(5); val names = rows.map { "${it.name} • ${it.mobile}" }.toTypedArray(); if (names.isEmpty()) toast("No borrower found") else AlertDialog.Builder(this).setTitle("Select borrower").setItems(names) { _, which -> borrower = rows[which].rowId; selected.text = "Selected: ${rows[which].name} • ${rows[which].id}" }.show() }); r.addView(button("CREATE BORROWER PROFILE", green) { profile("BORROWER", null) }); val type = Spinner(this); type.adapter = ArrayAdapter(this, android.R.layout.simple_spinner_dropdown_item, arrayOf("Personal Loan", "Trade Credit", "Rental / Lease", "Advance")); r.addView(fieldSpinner("CREDIT TYPE", type)); val amount = edit("0.00", null, true); val rate = edit("0.00", null, true); val tenor = edit("1", 3, true); val method = Spinner(this); method.adapter = ArrayAdapter(this, android.R.layout.simple_spinner_dropdown_item, arrayOf("EMI", "Principal + Interest", "One-time")); val start = edit("DD/MM/YYYY").apply { setText(SimpleDateFormat("dd/MM/yyyy", Locale.US).format(Date())) }; val end = edit("DD/MM/YYYY").apply { setText(start.text.toString()) }; r.addView(field("PRINCIPAL / CREDIT AMOUNT *", amount)); r.addView(field("ROI (% PER ANNUM) — DISPLAYED AS 0.00%", rate)); r.addView(fieldSpinner("REPAYMENT METHOD", method)); r.addView(field("TENOR (MONTHS)", tenor)); r.addView(field("START DATE", start)); r.addView(field("END DATE", end)); val calc = TextView(this).apply { textSize = 13f; setTextColor(navy); background = rounded(Color.WHITE, Color.LTGRAY, 10); setPadding(dp(10), dp(8), dp(10), dp(8)) }; r.addView(calc); r.addView(button("CALCULATE REPAYMENT", blue) { val p = amount.text.toString().toDoubleOrNull() ?: 0.0; val rr = rate.text.toString().toDoubleOrNull() ?: 0.0; val n = tenor.text.toString().toIntOrNull()?.coerceAtLeast(1) ?: 1; val emi = emi(p, rr, n); val payable = if (method.selectedItem.toString() == "One-time") p * (1 + rr / 100.0 * n / 12.0) else emi * n; calc.text = "Installment: ${money(emi)}\nROI: ${roi(rr)}\nTotal payable: ${money(payable)}" }); r.addView(button("CONTINUE → GUARANTOR", green) { val b = borrower; val p = amount.text.toString().toDoubleOrNull() ?: 0.0; if (b == null || p <= 0) { toast("Select borrower and enter amount"); return@button }; val rr = rate.text.toString().toDoubleOrNull() ?: 0.0; val n = tenor.text.toString().toIntOrNull()?.coerceAtLeast(1) ?: 1; val inst = emi(p, rr, n); val payable = if (method.selectedItem.toString() == "One-time") p * (1 + rr / 100.0 * n / 12.0) else inst * n; guarantorStep(Draft(b, null, type.selectedItem.toString(), p, rr, n, method.selectedItem.toString(), start.text.toString(), end.text.toString(), inst, payable)) }); show(r) }
    private fun fieldSpinner(title: String, s: Spinner) = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL; addView(label(title), LinearLayout.LayoutParams(-1, dp(23))); addView(s, LinearLayout.LayoutParams(-1, dp(45))) }
    private fun emi(p: Double, rr: Double, n: Int): Double { val m = rr / 1200.0; return if (m == 0.0) p / n else p * m * (1 + m).pow(n) / ((1 + m).pow(n) - 1) }

    private fun guarantorStep(d: Draft) { val r = page("Guarantor", "Step 2 • optional guarantor", ::dashboard); val sp = Spinner(this); sp.adapter = ArrayAdapter(this, android.R.layout.simple_spinner_dropdown_item, arrayOf("No guarantor", "Guarantor available")); r.addView(fieldSpinner("IS A GUARANTOR AVAILABLE?", sp)); val selected = TextView(this).apply { textSize = 13f; setTextColor(navy); setPadding(dp(8), dp(6), dp(8), dp(6)) }; r.addView(selected); var gid: Long? = null; r.addView(button("SEARCH GUARANTOR", teal) { val q = edit("Search guarantor"); AlertDialog.Builder(this).setTitle("Search guarantor").setView(q).setPositiveButton("SEARCH") { _, _ -> val rows = db.searchProfiles("GUARANTOR", q.text.toString()).take(5); if (rows.isEmpty()) toast("No guarantor found") else AlertDialog.Builder(this).setTitle("Select guarantor").setItems(rows.map { "${it.name} • ${it.mobile}" }.toTypedArray()) { _, w -> gid = rows[w].rowId; selected.text = "Selected: ${rows[w].name}" }.show() }.setNegativeButton("CANCEL", null).show() }); r.addView(button("CREATE GUARANTOR PROFILE", green) { profile("GUARANTOR", null) }); r.addView(button("CONTINUE → DOCUMENT & CONSENT", green) { consentFlow(d.copy(guarantor = if (sp.selectedItemPosition == 1) gid else null)) }); show(r) }

    private fun consentFlow(d: Draft) { currentCreditPdf = generatePdf(d); val r = page("Digital Documents & Consent", "Step 3 • legal-format document review", ::dashboard); r.addView(TextView(this).apply { text = "Demand Promissory Note / Credit Agreement"; textSize = 18f; setTextColor(navy) }); r.addView(TextView(this).apply { text = "The printable document contains lender, borrower, optional guarantor, amount, ROI, repayment method, dates and consent declarations. Have the parties review the document for correctness before consent."; textSize = 13f; setTextColor(Color.DKGRAY); setPadding(0, dp(5), 0, dp(5)) }); r.addView(button("VIEW / SHARE PRINTABLE PDF", navy) { sharePdf(currentCreditPdf) }); r.addView(button("LENDER CONSENT + OTP", blue) { otpDialog("Lender: verify and consent") { borrowerConsentStep(d) } }); show(r) }
    private fun borrowerConsentStep(d: Draft) { val r = page("Borrower Consent", "Step 3A • borrower must review first", ::dashboard); r.addView(TextView(this).apply { text = "Share the PDF with the borrower for review. Once the borrower confirms correctness, enter the OTP supplied by the borrower."; textSize = 14f; setTextColor(navy) }); r.addView(button("SHARE PDF WITH BORROWER", navy) { sharePdf(currentCreditPdf) }); r.addView(button("ENTER BORROWER CONSENT OTP", blue) { otpDialog("Borrower consent") { guarantorConsentStep(d) } }); show(r) }
    private fun guarantorConsentStep(d: Draft) { if (d.guarantor == null) { finalizeCredit(d); return }; val r = page("Guarantor Consent", "Step 3B • only when guarantor is applicable", ::dashboard); r.addView(TextView(this).apply { text = "Share the same final document with the guarantor. Enter the OTP supplied by the guarantor after acceptance."; textSize = 14f; setTextColor(navy) }); r.addView(button("SHARE PDF WITH GUARANTOR", navy) { sharePdf(currentCreditPdf) }); r.addView(button("ENTER GUARANTOR CONSENT OTP", blue) { otpDialog("Guarantor consent") { finalizeCredit(d) } }); show(r) }
    private fun finalizeCredit(d: Draft) { val id = db.addCredit(d.borrower, d.guarantor, d.type, "Credit Given", d.principal, d.roi, d.tenor, d.method, d.installment, (d.payable - d.principal).coerceAtLeast(0.0), d.payable, d.start, d.end, 0.0, "", null, "", false, d.end, 0); if (id > 0) AlertDialog.Builder(this).setTitle("Credit Registered Successfully").setMessage("Credit ID: ${db.creditDetail(id)?.creditId}\nROI: ${roi(d.roi)}\nThe repayment schedule is now available in Repayment Centre.").setPositiveButton("RECORD REPAYMENT") { _, _ -> repayments(false) }.setNegativeButton("DASHBOARD") { _, _ -> dashboard() }.show() else toast("Could not register credit") }

    private fun repayments(overdue: Boolean) { val r = page(if (overdue) "Overdue Repayments" else "Repayment Centre", "Record repayment for lender, borrower or guarantor", ::dashboard); val rows = db.schedules(overdue); if (rows.isEmpty()) r.addView(TextView(this).apply { text = "No pending repayments"; setTextColor(Color.GRAY) }); rows.forEach { s -> rcard(r, "${s.creditId} • Due ${s.dueDate}", "${money(s.amount)} • ${s.status}", if (s.status == "OVERDUE") red else green) { repaymentDialog(s.id, s.amount) } }; r.addView(button("RECORD OTHER / PARTIAL REPAYMENT", blue) { repaymentByCredit() }); show(r) }
    private fun repaymentDialog(scheduleId: Long, due: Double) { val e = edit("Payment amount", null, true); e.setText(String.format(Locale.US, "%.2f", due)); AlertDialog.Builder(this).setTitle("Record repayment").setView(e).setPositiveButton("SAVE") { _, _ -> val a = e.text.toString().toDoubleOrNull() ?: 0.0; if (a > 0 && db.recordPayment(scheduleId, a)) { toast("Repayment recorded"); repayments(false) } }.setNegativeButton("CANCEL", null).show() }
    private fun repaymentByCredit() { val rows = db.credits(); if (rows.isEmpty()) { toast("No credit accounts"); return }; AlertDialog.Builder(this).setTitle("Select credit").setItems(rows.map { "${it.creditId} • ${it.borrowerName} • ${money(it.amount)}" }.toTypedArray()) { _, w -> val c = rows[w]; val e = edit("Amount", null, true); AlertDialog.Builder(this).setTitle("Repayment for ${c.creditId}").setView(e).setPositiveButton("SAVE") { _, _ -> val a = e.text.toString().toDoubleOrNull() ?: 0.0; val schedule = db.schedules(false).firstOrNull { it.creditId == c.creditId }; if (schedule != null && a > 0) { db.recordPayment(schedule.id, a); toast("Repayment recorded") } }.setNegativeButton("CANCEL", null).show() }.show() }

    private fun history(direction: String?) { val r = page("Credit History", "ROI and repayment status", ::dashboard); db.credits(direction).forEach { c -> rcard(r, c.borrowerName, "${c.creditId} • ${money(c.amount)} • ROI ${roi(c.roi)} • ${c.method}\nOutstanding ${money((c.payable - db.paidForCredit(c.id)).coerceAtLeast(0.0))}", if (c.status == "ACTIVE") blue else red) { AlertDialog.Builder(this).setTitle(c.creditId).setMessage("Borrower: ${c.borrowerName}\nPrincipal: ${money(c.amount)}\nROI: ${roi(c.roi)}\nTotal payable: ${money(c.payable)}\nPaid: ${money(db.paidForCredit(c.id))}\nStart: ${c.start}\nEnd: ${c.end}").setPositiveButton("OK", null).show() } }; show(r) }
    private fun documents() { val r = page("Documents & Consent", "Printable legal-format records", ::dashboard); r.addView(button("SELECT SUPPORTING PDF / INVOICE", teal) { startActivity(Intent(Intent.ACTION_OPEN_DOCUMENT).apply { type = "application/pdf"; addCategory(Intent.CATEGORY_OPENABLE) }) }); r.addView(button("PROMISSORY NOTE WORKFLOW", navy) { toast("Promissory note is generated during credit registration and can be reviewed/shared before consent.") }); show(r) }
    private fun lender() { val u = db.userData(); val r = page("Lender Profile", "Edit profile and photo", ::dashboard); r.addView(TextView(this).apply { text = u?.name ?: ""; textSize = 22f; setTextColor(navy) }); r.addView(TextView(this).apply { text = "${u?.id}\n${u?.mobile}\n${u?.address}"; textSize = 13f; setTextColor(Color.GRAY) }); val img = ImageView(this).apply { layoutParams = LinearLayout.LayoutParams(-1, dp(135)); scaleType = ImageView.ScaleType.CENTER_CROP; u?.photo?.let { setImageURI(Uri.parse(it)) }; if (u?.photo.isNullOrBlank()) setImageResource(android.R.drawable.ic_menu_camera) }; r.addView(img); r.addView(button("CHANGE LENDER PHOTO", teal) { pickPhoto(img) }); r.addView(button("UPDATE LENDER PROFILE", green) { editLender(u) }); show(r) }
    private fun updateUserDirect(id: String, name: String, mobile: String, address: String, email: String, photo: String?) { val d = openOrCreateDatabase("udhaardaar_v32.db", MODE_PRIVATE, null); d.execSQL("UPDATE user_profile SET name=?, mobile=?, address=?, email=?, photo_uri=? WHERE unique_id=?", arrayOf(name, mobile, address, email, photo, id)); d.close() }
    private fun editLender(u: V32DatabaseHelper.User?) { val r = page("Edit Lender Profile", "Profile change", ::lender); val n = edit("Full name").apply { setText(u?.name ?: "") }; val m = phone("Mobile").apply { setText(u?.mobile ?: "") }; val a = edit("Address").apply { setText(u?.address ?: "") }; val e = edit("Email").apply { setText(u?.email ?: "") }; r.addView(field("FULL NAME", n)); r.addView(field("MOBILE", m)); r.addView(field("ADDRESS", a)); r.addView(field("EMAIL", e)); r.addView(button("SAVE CHANGES", green) { if (m.text.length != 10 || n.text.isNullOrBlank()) { toast("Enter valid name and mobile"); return@button }; updateUserDirect(u?.id ?: "", n.text.toString(), m.text.toString(), a.text.toString(), e.text.toString(), selectedPhoto?.toString() ?: u?.photo); selectedPhoto = null; lender() }); show(r) }

    private fun lookupPin(code: String, city: EditText, state: EditText, address: EditText) { Thread { try { val c = URL("https://api.postalpincode.in/pincode/$code").openConnection() as HttpURLConnection; c.connectTimeout = 5000; c.readTimeout = 5000; val body = c.inputStream.bufferedReader().use { it.readText() }; c.disconnect(); val root = JSONArray(body).getJSONObject(0); val rows = root.optJSONArray("PostOffice"); if (rows != null && rows.length() > 0) { val po = rows.getJSONObject(0); val cityName = po.optString("District").ifBlank { po.optString("Block") }; val stateName = po.optString("State"); val office = po.optString("Name"); Handler(Looper.getMainLooper()).post { city.setText(cityName); state.setText(stateName); if (address.text.isNullOrBlank()) address.setText("$office, $cityName, $stateName - $code") } } } catch (_: Exception) { } }.start() }
    private fun fillLocation(address: EditText, city: EditText, state: EditText, pin: EditText) { val lm = getSystemService(LOCATION_SERVICE) as LocationManager; if (ContextCompat.checkSelfPermission(this, Manifest.permission.ACCESS_FINE_LOCATION) != PackageManager.PERMISSION_GRANTED) { requestPermissions(arrayOf(Manifest.permission.ACCESS_FINE_LOCATION), 700); toast("Allow location permission and tap again"); return }; val loc = lm.getLastKnownLocation(LocationManager.GPS_PROVIDER) ?: lm.getLastKnownLocation(LocationManager.NETWORK_PROVIDER); if (loc == null) { startActivity(Intent(Settings.ACTION_LOCATION_SOURCE_SETTINGS)); toast("Turn on location and try again"); return }; Thread { try { val a = Geocoder(this, Locale.getDefault()).getFromLocation(loc.latitude, loc.longitude, 1)?.firstOrNull(); Handler(Looper.getMainLooper()).post { if (a != null) { address.setText(a.getAddressLine(0) ?: ""); city.setText(a.locality ?: a.subAdminArea ?: ""); state.setText(a.adminArea ?: ""); pin.setText(a.postalCode ?: "") } } } catch (_: Exception) { Handler(Looper.getMainLooper()).post { toast("Could not resolve current address") } } }.start() }

    private fun pickPhoto(target: ImageView) { photoTarget = target; startActivityForResult(Intent(Intent.ACTION_GET_CONTENT).apply { type = "image/*"; addCategory(Intent.CATEGORY_OPENABLE) }, 901) }
    override fun onActivityResult(requestCode: Int, resultCode: Int, data: Intent?) { super.onActivityResult(requestCode, resultCode, data); if (requestCode == 901 && resultCode == RESULT_OK) { selectedPhoto = data?.data; photoTarget?.setImageURI(selectedPhoto) } }
    private fun otpDialog(title: String, onVerified: () -> Unit) { pendingOtp = Random.nextInt(100000, 1000000).toString(); val e = edit("6-digit OTP", 6, true); AlertDialog.Builder(this).setTitle(title).setMessage("OTP generated for this verification step. In production, connect an approved SMS/OTP provider.\n\nDemo OTP: $pendingOtp").setView(e).setPositiveButton("VERIFY") { _, _ -> if (e.text.toString() == pendingOtp) onVerified() else toast("Incorrect OTP") }.setNegativeButton("CANCEL", null).show() }
    private fun generatePdf(d: Draft): File? { return try { val dir = File(cacheDir, "documents"); dir.mkdirs(); val f = File(dir, "Udhaardaar_${System.currentTimeMillis()}.pdf"); val doc = PdfDocument(); val page = doc.startPage(PdfDocument.PageInfo.Builder(595, 842, 1).create()); val p = Paint().apply { color = Color.BLACK; textSize = 13f }; var y = 48f; fun line(s: String, size: Float = 13f) { p.textSize = size; page.canvas.drawText(s.take(82), 42f, y, p); y += 22f }; line("DEMAND PROMISSORY NOTE / CREDIT AGREEMENT", 17f); y += 8f; val bp = db.profileData(d.borrower); val gp = d.guarantor?.let { db.profileData(it) }; line("Credit ID: DRAFT-${System.currentTimeMillis()}"); line("Date: ${SimpleDateFormat("dd/MM/yyyy", Locale.US).format(Date())}"); line("Lender: ${db.userData()?.name ?: ""}"); line("Borrower: ${bp?.name ?: ""} | Mobile: ${bp?.mobile ?: ""}"); if (gp != null) line("Guarantor: ${gp.name} | Mobile: ${gp.mobile}"); line("Principal: ${money(d.principal)}"); line("ROI: ${roi(d.roi)} per annum"); line("Repayment: ${d.method}"); line("Tenor: ${d.tenor} months"); line("Installment: ${money(d.installment)}"); line("Total payable: ${money(d.payable)}"); line("Start: ${d.start} | End: ${d.end}"); y += 10f; line("DECLARATION", 15f); line("The parties confirm that they have reviewed the above terms and"); line("agree that the information is correct before giving digital consent."); y += 20f; line("Lender consent: __________________  Date: __________"); line("Borrower consent: _______________  Date: __________"); if (gp != null) line("Guarantor consent: _______________  Date: __________"); y += 18f; line("This document is a digital record generated by Udhaardaar."); doc.finishPage(page); FileOutputStream(f).use { doc.writeTo(it) }; doc.close(); f } catch (_: Exception) { null } }
    private fun sharePdf(file: File?) { if (file == null) { toast("Could not generate PDF"); return }; val uri = FileProvider.getUriForFile(this, "${BuildConfig.APPLICATION_ID}.fileprovider", file); startActivity(Intent.createChooser(Intent(Intent.ACTION_SEND).apply { type = "application/pdf"; putExtra(Intent.EXTRA_STREAM, uri); addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION) }, "Share credit document")) }
    private fun toast(s: String) = Toast.makeText(this, s, Toast.LENGTH_LONG).show()
}
